import {
  Box,
  Button,
  FormControl,
  MenuItem,
  Paper,
  Select,
  Stack,
  Typography,
  CircularProgress,
  TextField,
  Chip,
  IconButton,
  Tooltip,
} from '@mui/material';
import PictureAsPdfIcon from '@mui/icons-material/PictureAsPdf';
import OpenInNewIcon from '@mui/icons-material/OpenInNew';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider, DatePicker } from '@mui/x-date-pickers';
import dayjs, { Dayjs } from 'dayjs';
import React, { useEffect, useMemo, useState } from 'react';
import { appColors, brandColors, HEADER_GRADIENT } from '../../../theme/appColors';
import DownloadIcon from '@mui/icons-material/Download';
import PrintIcon from '@mui/icons-material/Print';
import SummarizeIcon from '@mui/icons-material/Summarize';
import { useGetReferenceDataListQuery, useGetReportByReportNameQuery } from '../../posApi';
import PdfCanvasViewer from './PdfCanvasViewer';
import { IReferenceDataList } from '../../../core/Interface/referenceDataList.interface';

const SummaryReports = () => {
  const [pdfBlob, setPdfBlob] = useState<Blob | null>(null);
  const [pdfUrl, setPdfUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedReport, setSelectedReport] = useState('');
  const [fromDate, setFromDate] = useState<Dayjs | null>(dayjs());
  const [toDate, setToDate] = useState<Dayjs | null>(dayjs());

  const isDateRangeValid = !!fromDate?.isValid() && !!toDate?.isValid() && !fromDate.isAfter(toDate, 'day');

  const { data: referanceData } = useGetReferenceDataListQuery();

  const referanceDataList = useMemo(() => referanceData?.data as IReferenceDataList, [referanceData]);
  const reportTypeList = referanceDataList?.reports || [];
  const selectedReportLabel = reportTypeList.find((r) => r.key === selectedReport)?.value ?? selectedReport;

  const { data: reportData, isError, error, status } = useGetReportByReportNameQuery(
    {
      reportName: selectedReport,
      fromDate: fromDate?.startOf('day').format('YYYY-MM-DDTHH:mm:ss') ?? '',
      toDate: toDate?.endOf('day').format('YYYY-MM-DDTHH:mm:ss') ?? '',
    },
    { skip: !selectedReport || !isDateRangeValid }
  );

  const errorMessage =
    (error && 'data' in error && (error.data as { message?: string } | undefined)?.message) ||
    'Please try selecting the report again';

  useEffect(() => {
    setIsLoading(status === 'pending');
  }, [status]);

  useEffect(() => {
    if (reportData && !isError) {
      setPdfBlob(reportData);
      setPdfUrl(URL.createObjectURL(reportData));
    } else {
      setPdfBlob(null);
      setPdfUrl(null);
    }
  }, [reportData, isError]);

  useEffect(() => {
    return () => {
      if (pdfUrl) URL.revokeObjectURL(pdfUrl);
    };
  }, [pdfUrl]);

  const downloadPdf = () => {
    if (!pdfBlob) return;
    const url = URL.createObjectURL(pdfBlob);
    const link = document.createElement('a');
    link.href = url;
    const safeReportName = selectedReport
      .trim()
      .replace(/\s+/g, '_')
      .replace(/[^a-zA-Z0-9_-]/g, '');
    link.download = `${safeReportName}.pdf`;
    link.click();
  };

  const handlePrint = (blob: Blob) => {
    const url = URL.createObjectURL(blob);
    const iframe = document.createElement('iframe');
    iframe.style.display = 'none';
    iframe.src = url;
    iframe.onload = () => {
      iframe.contentWindow?.focus();
      iframe.contentWindow?.print();
      setTimeout(() => {
        URL.revokeObjectURL(url);
        document.body.removeChild(iframe);
      }, 1000);
    };
    document.body.appendChild(iframe);
  };

  return (
    <Box sx={{ backgroundColor: brandColors.contentBg, minHeight: '100%', p: { xs: 1.5, sm: 2 } }}>
      {/* Page Header */}
      <Paper
        elevation={0}
        sx={{ borderRadius: 2, mb: 2.5, overflow: 'hidden', boxShadow: '0 2px 12px rgba(15,29,77,0.12)' }}
      >
        {/* Gradient Title Bar */}
        <Box
          sx={{
            background: HEADER_GRADIENT,
            px: 3,
            py: 2,
            display: 'flex',
            alignItems: 'center',
            gap: 1.5,
          }}
        >
          <Box
            sx={{
              width: 38,
              height: 38,
              borderRadius: 1.5,
              backgroundColor: 'rgba(255,255,255,0.15)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              flexShrink: 0,
            }}
          >
            <SummarizeIcon sx={{ color: '#fff', fontSize: 22 }} />
          </Box>
          <Box>
            <Typography sx={{ color: '#fff', fontWeight: 700, letterSpacing: 0.3 }} variant="h6">
              Reports
            </Typography>
            <Typography sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }} variant="caption">
              Select a report type to preview and export
            </Typography>
          </Box>
        </Box>

        {/* Controls Bar */}
        <Box
          sx={{
            backgroundColor: '#fff',
            px: 3,
            py: 2,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            flexWrap: 'wrap',
            gap: 2,
            borderTop: '1px solid rgba(15,139,141,0.1)',
          }}
        >
          {/* Report Type Dropdown */}
          <FormControl
            size="small"
            sx={{
              minWidth: 260,
              '& .MuiOutlinedInput-root': {
                borderRadius: 1.5,
                backgroundColor: brandColors.contentBg,
                '&:hover .MuiOutlinedInput-notchedOutline': {
                  borderColor: brandColors.teal,
                },
                '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                  borderColor: brandColors.teal,
                },
              },
              '& .MuiInputLabel-root.Mui-focused': {
                color: brandColors.teal,
              },
            }}
          >
            <Select
              displayEmpty
              onChange={(e) => setSelectedReport(e.target.value)}
              renderValue={(selected) => {
                if (!selected) {
                  return (
                    <Typography sx={{ color: '#9ca3af', fontSize: '0.875rem' }}>
                      Select report type...
                    </Typography>
                  );
                }
                const found = reportTypeList.find((r) => r.key === selected);
                return found?.value ?? selected;
              }}
              value={selectedReport}
            >
              {reportTypeList.map((item) => (
                <MenuItem key={item.key} value={item.key}>
                  {item.value}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          {/* Date Range */}
          <LocalizationProvider dateAdapter={AdapterDayjs}>
            <Stack direction="row" spacing={1.5}>
              <DatePicker
                inputFormat="DD-MM-YYYY"
                label="From"
                maxDate={toDate ?? undefined}
                onChange={(date) => setFromDate(date)}
                renderInput={(params) => <TextField size="small" sx={{ width: 170 }} {...params} />}
                value={fromDate}
                views={['day', 'month', 'year']}
              />
              <DatePicker
                inputFormat="DD-MM-YYYY"
                label="To"
                minDate={fromDate ?? undefined}
                onChange={(date) => setToDate(date)}
                renderInput={(params) => <TextField size="small" sx={{ width: 170 }} {...params} />}
                value={toDate}
                views={['day', 'month', 'year']}
              />
            </Stack>
          </LocalizationProvider>

          {/* Action Buttons */}
          <Stack direction="row" spacing={1.5}>
            <Button
              disabled={isLoading || !pdfBlob}
              onClick={downloadPdf}
              startIcon={<DownloadIcon />}
              sx={{
                backgroundColor: brandColors.navy,
                color: '#fff',
                border: 'none',
                borderRadius: 1.5,
                px: 2,
                py: 0.75,
                fontWeight: 600,
                fontSize: '0.82rem',
                textTransform: 'none',
                '&:hover': { backgroundColor: brandColors.mid },
                '&:disabled': { backgroundColor: '#c9ccd6', color: '#fff' },
              }}
            >
              Download
            </Button>
            <Button
              disabled={isLoading || !pdfBlob}
              onClick={() => pdfBlob && handlePrint(pdfBlob)}
              startIcon={<PrintIcon />}
              sx={{
                backgroundColor: brandColors.teal,
                color: '#fff',
                border: 'none',
                borderRadius: 1.5,
                px: 2,
                py: 0.75,
                fontWeight: 600,
                fontSize: '0.82rem',
                textTransform: 'none',
                '&:hover': { backgroundColor: '#0a7375' },
                '&:disabled': { backgroundColor: 'rgba(15,139,141,0.4)', color: '#fff' },
              }}
            >
              Print
            </Button>
          </Stack>
        </Box>
      </Paper>

      {/* PDF Viewer */}
      <Paper
        elevation={0}
        sx={{ borderRadius: 2, overflow: 'hidden', boxShadow: '0 1px 8px rgba(0,0,0,0.07)', minHeight: 200 }}
      >
        {!selectedReport && (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              py: 12,
              gap: 1.5,
            }}
          >
            <SummarizeIcon sx={{ fontSize: 52, color: '#d1d5db' }} />
            <Typography sx={{ color: '#9ca3af', fontWeight: 600, fontSize: '0.95rem' }}>
              No report selected
            </Typography>
            <Typography sx={{ color: '#d1d5db', fontSize: '0.82rem' }}>
              Choose a report type from the dropdown above
            </Typography>
          </Box>
        )}

        {selectedReport && isLoading && (
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', py: 10 }}>
            <Stack spacing={2} alignItems="center">
              <CircularProgress size={36} sx={{ color: brandColors.teal }} />
              <Typography sx={{ color: '#6b7280', fontSize: '0.88rem' }}>Loading report...</Typography>
            </Stack>
          </Box>
        )}

        {isError && !isLoading && (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              py: 10,
              gap: 1,
            }}
          >
            <SummarizeIcon sx={{ fontSize: 48, color: appColors.carmineRed[60] }} />
            <Typography sx={{ color: appColors.carmineRed[100], fontWeight: 600 }}>
              Failed to load report
            </Typography>
            <Typography sx={{ color: '#6b7280', fontSize: '0.84rem' }}>
              {errorMessage}
            </Typography>
          </Box>
        )}

        {pdfUrl && !isLoading && !isError && (
          <>
            {/* Viewer Header */}
            <Box
              sx={{
                px: 3,
                py: 1.5,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                gap: 2,
                flexWrap: 'wrap',
                borderBottom: '1px solid #eceef2',
              }}
            >
              <Stack direction="row" spacing={1.25} alignItems="center" sx={{ minWidth: 0 }}>
                <PictureAsPdfIcon sx={{ color: appColors.carmineRed[60], fontSize: 22 }} />
                <Typography noWrap sx={{ color: brandColors.navy, fontWeight: 600, fontSize: '0.95rem' }}>
                  {selectedReportLabel}
                </Typography>
                <Chip
                  label={`${fromDate?.format('DD MMM YYYY')} – ${toDate?.format('DD MMM YYYY')}`}
                  size="small"
                  sx={{
                    backgroundColor: 'rgba(15,139,141,0.08)',
                    color: brandColors.teal,
                    fontWeight: 500,
                    fontSize: '0.75rem',
                  }}
                />
              </Stack>
              <Tooltip title="Open in new tab">
                <IconButton onClick={() => window.open(pdfUrl, '_blank')} size="small" sx={{ color: '#6b7280' }}>
                  <OpenInNewIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            </Box>

            {/* Document Canvas */}
            <Box
              sx={{
                backgroundColor: '#eef0f3',
                p: { xs: 1, sm: 3 },
                display: 'flex',
                justifyContent: 'center',
                maxHeight: 'calc(100vh - 300px)',
                minHeight: 520,
                overflowY: 'auto',
              }}
            >
              <Box sx={{ width: '100%', maxWidth: 900 }}>
                {pdfBlob && <PdfCanvasViewer blob={pdfBlob} />}
              </Box>
            </Box>
          </>
        )}
      </Paper>
    </Box>
  );
};

export default SummaryReports;
